  (3201, 2002, '您关注的「周杰伦上海站」即将开票，别忘了设置提醒。', 0, '演出提醒', '2026-11-06 10:00:00', '2026-11-06 10:00:00'),
  (3202, 2002, '提醒已经开了，谢谢', 1, NULL, '2026-11-06 10:10:00', '2026-11-06 10:10:00'),
  (3301, 2003, '订单 PN20261108000001 已出票，可在「我的订单」查看电子票。', 0, '订单助手', '2026-11-05 10:00:00', '2026-11-05 10:00:00'),
  (3501, 2005, '上海站加场了，明天十点开抢。', 0, '抢票小分队', '2026-11-02 11:30:00', '2026-11-02 11:30:00'),
  (3502, 2005, '收到，明天守着', 1, NULL, '2026-11-02 11:42:00', '2026-11-02 11:42:00'),
  (3503, 2005, '加场是周五场，票档和原来一样。', 0, '抢票小分队', '2026-11-02 11:55:00', '2026-11-02 11:55:00');
