INSERT INTO `activity_detail` (`detail_id`, `activity_id`, `detail_desc`, `type`, `gmt_create`, `gmt_modified`) VALUES
  (1001501, 1001, '华语乐坛天王周杰伦「最伟大的作品」世界巡回演唱会上海站。本次巡演以第十张专辑《最伟大的作品》为核心，融合古典、中国风与流行电音，舞台采用 360 度环形屏与可升降机械装置，还原 MV 中的名画场景。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (1001502, 1001, '本场演出为实名制购票，一人一证一票，入场需携带购票时填写的身份证原件。；演出票一经售出，除演出取消外不支持退换。；1.2 米以下儿童谢绝入场，1.2 米以上儿童凭票入场。', 2, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (1002501, 1002, '五月天 25 周年巡回演唱会，跨 20 年的歌单一次唱完。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (1003501, 1003, '陈奕迅以「FEAR AND DREAMS」为题，用一场演唱会讲完一个完整的故事。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (1004501, 1004, '两天四舞台，华语独立音乐与生活市集。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (1005501, 1005, 'JJ20 巡演最终章，二十年代表作全收录。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (2001501, 2001, '韦伯经典音乐剧《剧院魅影》首个官方中文版。巴黎歌剧院的地下湖、吊灯坠落、以及那首《The Phantom of the Opera》，全部按百老汇原版舞美 1:1 复刻。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (2001502, 2001, '本场演出 1.2 米以下儿童谢绝入场。；演出票一经售出，除演出取消外不支持退换。；迟到观众需在场间休息时入场。', 2, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (2002501, 2002, '两个剧组抢同一个舞台，一悲一喜，三十多年长演不衰。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (2003501, 2003, '法语音乐剧里程碑，全剧以 50 余首摇滚风格歌曲串起雨果原著。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (2004501, 2004, '戴着面具在五层楼里自由行走，每条动线都是一个不同的故事。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (2004502, 2004, '演出全程需佩戴面具，请穿着便于行走的鞋子。；场内禁止拍照与录像。', 2, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (2005501, 2005, '「你是我温暖的手套，冰冷的啤酒。」中国小剧场话剧的票房神话。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (3001501, 3001, '维也纳爱乐乐团亚洲巡演上海站，曲目为勃拉姆斯与布鲁克纳。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (3002501, 3002, '郎朗带来巴赫《哥德堡变奏曲》全集。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (3003501, 3003, '《天空之城》《龙猫》《千与千寻》配乐现场演奏 + 大屏影像。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (4001501, 4001, '改编自同名畅销童书，用音乐剧带孩子逛一遍故宫。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (4001502, 4001, '儿童一律凭票入场，无免票政策。', 2, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (4002501, 4002, '佩奇一家人的雨天冒险，全场互动。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (5001501, 5001, '6600 平方米、50 余件数字艺术作品，没有地图也没有边界。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (5002501, 5002, '400 余幅莫奈作品的高清投影，沉浸式还原吉维尼花园。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (6001501, 6001, '俄罗斯古典芭蕾的标杆版本，白天鹅与黑天鹅同台。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (6002501, 6002, '以身体为唯一语言的极简作品，无音乐、无布景。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (7001501, 7001, '郭德纲、于谦领衔，德云社一年一度的上海专场。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (7002501, 7002, '一票难求的脱口秀现场，阵容以演出当天为准。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (7002502, 7002, '本场演出建议 18 岁以上观众观看。', 2, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (7003501, 7003, '《四郎探母》《锁麟囊》等经典折子戏连演。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (8001501, 8001, '上海德比，两队本赛季第二次交手。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (8001502, 8001, '入场需携带身份证原件，一人一证一票。', 2, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (8002501, 8002, 'LPL 春季赛常规赛，每日两场 BO3。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (9001501, 9001, '国家大剧院制作版《茶花女》，三层旋转舞台。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (9002501, 9002, '老舍原著，焦菊隐导演版，北京人艺的看家戏。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (9003501, 9003, '三天三舞台，华东地区规模最大的户外音乐节之一。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
  (9004501, 9004, '徐俊导演作品，以音乐剧重述中国古典悲剧。', 1, '2026-10-01 00:00:00', '2026-10-01 00:00:00'),
