INSERT INTO `feed` (`feed_id`, `type`, `user_id`, `user`, `content`, `title`, `name`, `poster`, `price`, `amount`, `is_liked`, `likes`, `reply_count`, `shares`, `views`, `click_num`, `rank_weight`, `is_quality`, `status`, `feed_num`, `want_watch_num`, `images`, `videos`, `tags`, `topic_list`, `activity`, `gmt_create`, `gmt_modified`) VALUES
  (1, 1, 10, '{"userId":10,"userName":"剧院常驻民"}', '序曲一响就知道这版是认真的。吊灯升起的段落用的是原版机械结构，从头顶掠过时能听到轨道滑动的声音。 中文唱词比我预期自然，几个关键段落没有被翻译腔拖住。二层楼座中区是性价比最高的位置，能同时看到乐池和舞台深度。', '《剧院魅影》中文版首演repo：吊灯落下的那一刻全场屏住呼吸', '网友热议', NULL, 0.0, 0, 0, 1208, 3, 0, 32400, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":1,"name":"网友热议"}]', '[{"id":1,"name":"网友热议"}]', '{"activityId":2001,"name":"音乐剧《剧院魅影》中文版"}', '2026-11-06 09:00:00', '2026-11-06 09:00:00'),
  (2, 2, 11, '{"userId":11,"userName":"抢票小分队"}', '开票后 15 分钟、开演前 7 天、开演前 48 小时——这三个时间点是退票回流最集中的窗口。 前两个靠蹲，第三个靠"回流提醒"。另外内场 A 区靠后的位置其实视野被前区挡住，别为了区域名多花钱。', '周杰伦上海站抢票攻略：这三个时间点最容易捡漏', '攻略', NULL, 0.0, 0, 0, 4560, 2, 0, 128000, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":2,"name":"攻略"}]', '[{"id":2,"name":"攻略"}]', '{"activityId":1001,"name":"周杰伦「最伟大的作品」世界巡回演唱会 上海站"}', '2026-11-06 07:00:00', '2026-11-06 07:00:00'),
  (3, 1, 12, '{"userId":12,"userName":"看展的猫"}', '工作日上午 10 点第一场人最少，光影馆基本能空场拍。 推荐机位：镜像球体区（低角度）、水晶宇宙（贴近地面仰拍）、以及出口前的花与人房间。手机记得关自动测光，不然会过曝。', 'teamLab 无界美术馆拍照机位整理，附最佳入场时间', '观演repo', NULL, 0.0, 0, 0, 902, 1, 0, 18600, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":3,"name":"观演repo"}]', '[{"id":3,"name":"观演repo"}]', '{"activityId":5001,"name":"teamLab 无界美术馆 常设展"}', '2026-11-06 04:00:00', '2026-11-06 04:00:00'),
  (4, 1, 13, '{"userId":13,"userName":"沉浸式爱好者"}', '面具戴上之后没人说话，全靠眼神和跟随。建议第一轮先跟着主线，第二轮再单独追一个角色——不然会在楼梯间迷路。 穿好走的鞋，全程三小时基本在站和走。', '第一次看《不眠之夜》，跟着演员跑了三层楼，值回票价', '网友热议', NULL, 0.0, 0, 0, 431, 0, 0, 9800, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":1,"name":"网友热议"}]', '[{"id":1,"name":"网友热议"}]', '{"activityId":2004,"name":"沉浸式戏剧《不眠之夜》Sleep No More"}', '2026-11-06 01:00:00', '2026-11-06 01:00:00'),
  (5, 1, 14, '{"userId":14,"userName":"选座研究所"}', '大剧院的池座后排有遮挡，楼座 2 层虽然远但视线完整，而且票价比池座后排低一档。 看话剧优先选正对舞台的楼座 1 层前区；看舞剧选偏一点的侧区，因为调度会用到舞台深处。', '上海大剧院选座指南：楼座 2 层其实比池座后排看得清', '攻略', NULL, 0.0, 0, 0, 1540, 2, 0, 24100, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":2,"name":"攻略"}]', '[{"id":2,"name":"攻略"}]', '{"activityId":2002,"name":"话剧《暗恋桃花源》经典版"}', '2026-11-05 12:00:00', '2026-11-05 12:00:00'),
  (6, 2, 15, '{"userId":15,"userName":"阿信的迷妹"}', '安可第三首才是《温柔》，全场自动打开手机灯。 内场站区很挤，体力不好的建议看台。音响这次调得不错，低音没有糊。', '五月天现场｜25 年了，合唱《温柔》的时候还是想哭', '网友热议', NULL, 0.0, 0, 0, 3320, 0, 0, 76500, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":1,"name":"网友热议"}]', '[{"id":1,"name":"网友热议"}]', '{"activityId":1002,"name":"五月天「回到那一天」25 周年巡回演唱会 上海站"}', '2026-11-05 08:00:00', '2026-11-05 08:00:00'),
  (7, 1, 16, '{"userId":16,"userName":"两个娃的妈"}', '读过绘本的孩子能认出角色，全程注意力明显更集中。 演出 70 分钟没有中场，5 岁以下建议坐靠走道的位置，方便中途出去。', '带孩子看《故宫里的大怪兽》前，先读一遍绘本会更好', '亲子', NULL, 0.0, 0, 0, 288, 0, 0, 6400, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":4,"name":"亲子"}]', '[{"id":4,"name":"亲子"}]', '{"activityId":4001,"name":"亲子音乐剧《故宫里的大怪兽》"}', '2026-11-04 12:00:00', '2026-11-04 12:00:00'),
  (8, 1, 17, '{"userId":17,"userName":"看台第十二人"}', '主场看台的助威是有组织的，跟着喊两轮就上手了。 散场地铁比想象中快，建议走 2 号口。', '中超德比观赛体验：浦东足球场的声浪是真的顶', '观演repo', NULL, 0.0, 0, 0, 640, 0, 0, 12900, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":3,"name":"观演repo"}]', '[{"id":3,"name":"观演repo"}]', '{"activityId":8001,"name":"中超联赛 上海海港 vs 上海申花"}', '2026-11-04 06:00:00', '2026-11-04 06:00:00'),
  (9, 1, 18, '{"userId":18,"userName":"音乐剧搬运工"}', '开场《大教堂时代》的合唱层次比录音版更厚，现场乐队的铜管是加分项。 字幕屏位置偏高，坐前区需要抬头，介意的话选后区。', '《巴黎圣母院》法语原版：大教堂时代一响，鸡皮疙瘩起来了', '网友热议', NULL, 0.0, 0, 0, 812, 0, 0, 15700, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":1,"name":"网友热议"}]', '[{"id":1,"name":"网友热议"}]', '{"activityId":2003,"name":"法语原版音乐剧《巴黎圣母院》"}', '2026-11-03 12:00:00', '2026-11-03 12:00:00'),
  (10, 1, 19, '{"userId":19,"userName":"段子收集器"}', '线上的段子到了现场有一半是新的，互动环节才是主场优势。 前排会被点名，社恐请坐中后区。', '脱口秀现场和线上完全两种体验，笑到腮帮子疼', '观演repo', NULL, 0.0, 0, 0, 356, 0, 0, 8200, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":3,"name":"观演repo"}]', '[{"id":3,"name":"观演repo"}]', '{"activityId":7002,"name":"脱口秀《脱口秀大会》巡演 上海站"}', '2026-11-03 04:00:00', '2026-11-03 04:00:00'),
  (11, 1, 20, '{"userId":20,"userName":"芭蕾笔记"}', '黑天鹅双人舞的挥鞭转是全场顶点，乐团跟着加快了半拍。 看芭蕾建议选侧前方，能看清足尖和手臂线条。', '马林斯基《天鹅湖》32 个挥鞭转，现场掌声持续了两分钟', '观演repo', NULL, 0.0, 0, 0, 1102, 0, 0, 21300, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":3,"name":"观演repo"}]', '[{"id":3,"name":"观演repo"}]', '{"activityId":6001,"name":"马林斯基剧院芭蕾舞团《天鹅湖》"}', '2026-11-02 12:00:00', '2026-11-02 12:00:00'),
  (12, 1, 21, '{"userId":21,"userName":"相声票友"}', '返场比正活还长，观众接梗接得比演员还快。 园子小，最后一排也听得清，不用抢前排。', '德云社上海专场：郭德纲一开口，全场就开始接梗', '网友热议', NULL, 0.0, 0, 0, 2204, 0, 0, 44800, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":1,"name":"网友热议"}]', '[{"id":1,"name":"网友热议"}]', '{"activityId":7001,"name":"德云社 郭德纲·于谦 相声专场"}', '2026-11-02 03:00:00', '2026-11-02 03:00:00'),
  (13, 1, 22, '{"userId":22,"userName":"古典乐手记"}', '布鲁克纳第七的慢乐章是这场的关键，建议提前听两遍再进场，现场的信息量会大很多。 乐章之间不要鼓掌，这是这类音乐会的基本礼仪。', '维也纳爱乐来了，这次曲目单里有一首很少演的布鲁克纳', '攻略', NULL, 0.0, 0, 0, 240, 0, 0, 5600, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":2,"name":"攻略"}]', '[{"id":2,"name":"攻略"}]', '{"activityId":3001,"name":"维也纳爱乐乐团 2026 上海音乐会"}', '2026-11-01 12:00:00', '2026-11-01 12:00:00'),
  (14, 2, 23, '{"userId":23,"userName":"音乐节地图"}', '主舞台压轴之外，第二天下午的微风舞台是隐藏彩蛋。 两天通票比单日划算，但体力要留够。草地早晚温差大，带件外套。', '简单生活节两天全记录：哪个舞台值得蹲一整天', '攻略', NULL, 0.0, 0, 0, 1680, 0, 0, 33100, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":2,"name":"攻略"}]', '[{"id":2,"name":"攻略"}]', '{"activityId":1004,"name":"2026 简单生活节 上海"}', '2026-11-01 05:00:00', '2026-11-01 05:00:00'),
  (15, 1, 24, '{"userId":24,"userName":"召唤师峡谷"}', '大屏导播切得比直播快，团战能提前半秒看到结果。 场馆内餐饮偏贵，建议提前吃。', 'LPL 春季赛现场：解说声音比直播间大十倍', '观演repo', NULL, 0.0, 0, 0, 2460, 0, 0, 51200, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":3,"name":"观演repo"}]', '[{"id":3,"name":"观演repo"}]', '{"activityId":8002,"name":"2026 英雄联盟职业联赛 LPL 春季赛 上海站"}', '2026-10-31 12:00:00', '2026-10-31 12:00:00'),
  (16, 1, 25, '{"userId":25,"userName":"小剧场常客"}', '"你是我温暖的手套，冰冷的啤酒"——这句一出来就没绷住。 小剧场第一排会有互动，想安静看戏的选后排。', '《恋爱的犀牛》看了三遍，每次都在同一句台词掉眼泪', '观演repo', NULL, 0.0, 0, 0, 198, 0, 0, 4100, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":3,"name":"观演repo"}]', '[{"id":3,"name":"观演repo"}]', '{"activityId":2005,"name":"孟京辉戏剧作品《恋爱的犀牛》"}', '2026-10-30 12:00:00', '2026-10-30 12:00:00'),
  (17, 1, 26, '{"userId":26,"userName":"周末带娃"}', '曲目选了《千与千寻》《龙猫》这些熟悉的段落，孩子能跟上。 亲子场允许小声说话，不用担心被侧目，这点很友好。', '久石让音乐会亲子场：孩子全程没走神，这就够了', '亲子', NULL, 0.0, 0, 0, 312, 0, 0, 7300, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":4,"name":"亲子"}]', '[{"id":4,"name":"亲子"}]', '{"activityId":3003,"name":"久石让·宫崎骏 动漫交响音乐会"}', '2026-10-29 12:00:00', '2026-10-29 12:00:00'),
  (18, 1, 12, '{"userId":12,"userName":"看展的猫"}', '投影区大概 20 分钟一轮，建议进去就坐下等完整一轮。 静态展区的真迹不多，主要看氛围。', '印象莫奈展：投影区比静态展区好看太多', '观演repo', NULL, 0.0, 0, 0, 146, 0, 0, 3800, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":3,"name":"观演repo"}]', '[{"id":3,"name":"观演repo"}]', '{"activityId":5002,"name":"印象莫奈 时光映迹艺术展"}', '2026-10-28 12:00:00', '2026-10-28 12:00:00'),
  (19, 2, 27, '{"userId":27,"userName":"港乐三十年"}', '舞台是环绕式投影，四面台都能看到完整视觉。 歌单偏后期作品，想听老歌的要有心理准备。', '陈奕迅 FEAR AND DREAMS：舞台设计是这几年最好的', '网友热议', NULL, 0.0, 0, 0, 2980, 0, 0, 62700, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":1,"name":"网友热议"}]', '[{"id":1,"name":"网友热议"}]', '{"activityId":1003,"name":"陈奕迅 FEAR AND DREAMS 世界巡回演唱会 上海站"}', '2026-10-27 12:00:00', '2026-10-27 12:00:00'),
  (20, 1, 28, '{"userId":28,"userName":"戏迷老王"}', '三折戏里《三岔口》的哑剧段落最精彩，全靠身段。 剧场不大，最后一排也看得清脸谱。', '上海京剧院折子戏：80 块能看到这个水平，太值了', '观演repo', NULL, 0.0, 0, 0, 88, 0, 0, 2400, 0, 0, 0, 1, 0, 0, '[]', '[]', '[{"id":3,"name":"观演repo"}]', '[{"id":3,"name":"观演repo"}]', '{"activityId":7003,"name":"上海京剧院 经典折子戏专场"}', '2026-10-25 12:00:00', '2026-10-25 12:00:00');
